<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Property; use App\Modules\Property\Application\Actions\ApprovePropertyAction; use Illuminate\Http\Request;
class PropertyModerationController extends Controller {public function index(){return view('admin.properties.pending',['properties'=>Property::with(['translations','owner'])->where('status','pending_review')->paginate(30)]);} public function approve(Property $property,ApprovePropertyAction $action){$this->authorize('approve',$property);$action->execute($property,auth()->id());return back()->with('success','Property approved.');} public function reject(Request $request,Property $property){$this->authorize('approve',$property);$data=$request->validate(['reason'=>['required','string','max:1000']]);$old=$property->status?->value;$property->update(['status'=>'rejected']);$property->statusHistory()->create(['old_status'=>$old,'new_status'=>'rejected','changed_by'=>auth()->id(),'reason'=>$data['reason']]);return back()->with('success','Property rejected.');}}
